/*
 * M3 (GC seam, leaf 5; pattern M3-CANVAS-BACKGROUND v1): the Paint GC of an M3 canvas (a GCExtension) has no device context
 * and no GCData, so drawBackground (gc, ...) fills through the GC, in points, with the choice of drawBackground (hDC, ...):
 * the background control's image tiled from its client origin moved by the offset, else its colour, else the GC's
 * background (a theme background is filled with that colour). StyledText fills its margins and line backgrounds this way.
 */
void drawBackgroundThroughGC (GC gc, int x, int y, int width, int height, int offsetX, int offsetY) {
	int zoom = getAutoscalingZoom ();
	Rectangle area = Win32DPIUtils.pixelToPoint (new Rectangle (x, y, width, height), zoom);
	Control control = findBackgroundControl ();
	if (control != null && control.backgroundImage != null) {
		tileBackgroundThroughGC (gc, control.backgroundImage, display.map (control, this, 0, 0), area,
			DPIUtil.pixelToPoint (offsetX, zoom), DPIUtil.pixelToPoint (offsetY, zoom));
		return;
	}
	Color previous = gc.getBackground ();
	if (control != null) gc.setBackground (Color.win32_new (display, control.getBackgroundPixel ()));
	gc.fillRectangle (area);
	gc.setBackground (previous);
}

/* the image tiled over the area (points), the tiles aligned on the origin moved by the offset; the GC's clipping restored */
void tileBackgroundThroughGC (GC gc, Image image, Point origin, Rectangle area, int offsetX, int offsetY) {
	Rectangle tile = image.getBounds ();
	int startX = area.x - Math.floorMod (area.x - origin.x + offsetX, tile.width);
	int startY = area.y - Math.floorMod (area.y - origin.y + offsetY, tile.height);
	Region saved = gc.isClipped () ? new Region (display) : null;
	if (saved != null) gc.getClipping (saved);
	gc.setClipping (area.intersection (gc.getClipping ()));
	for (int ty = startY; ty < area.y + area.height; ty += tile.height) {
		for (int tx = startX; tx < area.x + area.width; tx += tile.width) gc.drawImage (image, tx, ty);
	}
	gc.setClipping (saved);
	if (saved != null) saved.dispose ();
}

